'use strict';
function mlTable(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function mlView(){const m=APRENDIZADO,c=m.classifier.calibrated,r=m.regression.model,nb=m.regression.nb2_reference,g=m.clusters;$('#ml-summary').innerHTML='<b>Conclusão da extensão</b><p>Ganho preditivo modesto nas probabilidades de gravidade e na previsão de contagens. O agrupamento encontra perfis reprodutíveis dentro do universo inicial; ele ajuda a selecionar casos, sem medir qualidade institucional.</p>';
$('#ml-classifier').innerHTML=mlTable(['Modelo · teste 2024–2025','Log loss ↓','Brier ↓','Acurácia'],[['Distribuição constante',N(m.classifier.reference.log_loss,3),N(m.classifier.reference.brier,3),N(100*m.classifier.reference.accuracy,1)+'%'],['Multinomial',N(m.classifier.multinomial_reference.log_loss,3),N(m.classifier.multinomial_reference.brier_multiclasse,3),N(100*m.classifier.multinomial_reference.accuracy,1)+'%'],['Boosting + temperatura',N(c.log_loss,3),N(c.brier,3),N(100*c.accuracy,1)+'%']]);
plot('ml-class-chart',{grid:{left:80,right:20,top:25,bottom:55},xAxis:{type:'category',data:['Sem vítimas','Leves','Graves','Mortes'],axisLabel:{interval:0}},yAxis:{type:'value',max:100,axisLabel:{formatter:v=>v+'%'}},series:[{type:'bar',data:c.recall.map(x=>x*100),itemStyle:{color:C.teal},label:{show:true,position:'top',formatter:p=>N(p.value,1)+'%'}}]});$('#ml-class-reading').innerHTML='<b>Melhora probabilidades; identificação fatal segue baixa</b><p>Sensibilidade fatal '+N(100*c.recall[3],1)+'% ao escolher a maior probabilidade. AP fatal '+N(c.fatal_ap,3)+' versus prevalência de '+N(c.fatal_prevalence,3)+'. O gráfico mostra a sensibilidade de cada classe, não a proporção dos eventos.</p><p>A classificação usa características conhecidas no registro, inclusive tipo do sinistro. Não prevê acidentes antes de ocorrerem e não está validada para decisão operacional.</p>';
$('#ml-regression').innerHTML=mlTable(['Modelo · mortes','Desvio Poisson ↓','MAE ↓'],[['Taxa constante',N(m.regression.reference.poisson_deviance,3),N(m.regression.reference.mae,3)],['NB2',N(nb.mean_poisson_deviance,3),N(nb.mae,3)],['Boosting Poisson',N(r.poisson_deviance,3),N(r.mae,3)]]);let cal=m.regression.calibration;plot('ml-reg-chart',{grid:{left:70,right:20,top:30,bottom:45},legend:{top:0},xAxis:{type:'category',data:cal.map(x=>'D'+x.decile)},yAxis:{type:'value'},series:[{name:'Mortes observadas',type:'line',data:cal.map(x=>x.observed)},{name:'Mortes previstas',type:'line',data:cal.map(x=>x.predicted)}]});$('#ml-reg-reading').innerHTML='<b>Ganho temporal de '+N(100*(1-r.poisson_deviance/nb.mean_poisson_deviance),1)+'% no desvio frente ao NB2</b><p>Foram observadas '+N(r.observed)+' mortes e previstas '+N(r.predicted)+'. A figura agrega segmentos em dez grupos de previsão crescente, sem representar meses. Exposição PNCT é tratada como conhecida, embora seja modelada.</p><p>Uma observação mal prevista deve ser investigada. Resíduo não identifica sinistro oculto ou falha de governança.</p>';
let cs=m.classifier_spatial.calibrated,rs=m.regression_spatial.model;$('#ml-spatial').innerHTML=mlTable(['Experimento','Amostra de teste','Resultado','Referência constante'],[['Gravidade',N(cs.n)+' ocorrências','Log loss '+N(cs.log_loss,3),'Log loss '+N(m.classifier_spatial.reference.log_loss,3)],['Mortes com exposição',N(rs.n)+' segmentos-ano','Desvio '+N(rs.poisson_deviance,3),'Desvio '+N(m.regression_spatial.reference.poisson_deviance,3)]]);
$('#ml-clusters').innerHTML='<p>'+N(g.n)+' segmentos com os mesmos limites em 2022 e 2023; '+g.selected.k+' grupos. Silhouette '+N(g.selected.silhouette,3)+'; ARI médio '+N(g.selected.ari_mean,3)+' em oito subamostras de 80%. A disponibilidade futura de limites idênticos cobre '+N(100*g.future_matching_segments/g.n,1)+'% do universo inicial.</p>'+mlTable(['Grupo','Trechos','VMD mediano','Sinistros / 100 mi veículos-km'],g.profiles.map(p=>['G'+p.group,N(p.segments),N(p.vmda_median),N(p.crash_rate,2)]));plot('ml-cluster-chart',{grid:{left:45,right:20,top:25,bottom:45},legend:{top:0},xAxis:{type:'value',name:'PCA 1',nameLocation:'middle',nameGap:26},yAxis:{type:'value',name:'PCA 2'},series:g.profiles.map(p=>({name:'G'+p.group,type:'scatter',symbolSize:4,data:g.scatter.filter(s=>s[2]===p.group).map(s=>s.slice(0,2)),itemStyle:{opacity:.45}}))});
$('#ml-importance').innerHTML='<h3>Classificação · aumento da log loss</h3>'+mlTable(['Campo','Importância','Variação entre repetições'],m.classifier.importance.sort((a,b)=>b.delta_log_loss-a.delta_log_loss).map(x=>[esc(x.feature),N(x.delta_log_loss,4),N(x.sd,4)]))+'<h3>Regressão · aumento do desvio</h3>'+mlTable(['Campo','Importância','Variação entre repetições'],m.regression.importance.sort((a,b)=>b.delta_deviance-a.delta_deviance).map(x=>[esc(x.feature),N(x.delta_deviance,4),N(x.sd,4)]));}
const mlRender=render;render=function(){mlRender();if(state.page==='aprendizado')mlView()};const mlPage=page;page=function(id){mlPage(id);if(id==='aprendizado'){$('#page-label').textContent='Aprendizado de máquina';$('.filters').style.opacity='.48';$$('.filters select').forEach(e=>e.disabled=true);$('#scope').textContent='Experimentos nacionais fixos · não reestimados pelos filtros';$('#export').style.display='none'}};page(location.hash.slice(1)||'visao');
